#!/bin/sh
# Install m7ctl for the current user (Linux; on Windows and macOS copy the binary anywhere on PATH).
#   ./dist/install.sh            link ~/.local/bin/m7ctl to the release build (rebuilds are picked up)
#   ./dist/install.sh --copy     copy the binary instead (stays put if this folder moves)
#   ./dist/install.sh --no-udev  skip the udev rule (it needs sudo)
#   ./dist/install.sh --uninstall
set -eu

here=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
bin="$here/target/release/m7ctl"
dest_bin="$HOME/.local/bin/m7ctl"
data="${XDG_DATA_HOME:-$HOME/.local/share}"
conf="${XDG_CONFIG_HOME:-$HOME/.config}"
rule_src="$here/dist/udev/70-machenike-m7.rules"
rule_dst=/etc/udev/rules.d/70-machenike-m7.rules

mode=link; udev=yes; uninstall=no
for a in "$@"; do
    case "$a" in
        --copy) mode=copy ;;
        --no-udev) udev=no ;;
        --uninstall) uninstall=yes ;;
        -h|--help) sed -n '2,6p' "$0"; exit 0 ;;
        *) echo "unknown option: $a" >&2; exit 2 ;;
    esac
done

targets="$dest_bin
$data/bash-completion/completions/m7ctl
$data/zsh/site-functions/_m7ctl
$conf/fish/completions/m7ctl.fish
$data/man/man1/m7ctl.1"

if [ "$uninstall" = yes ]; then
    echo "$targets" | while IFS= read -r f; do
        if [ -e "$f" ] || [ -L "$f" ]; then rm -f "$f"; echo "removed $f"; fi
    done
    if [ -e "$rule_dst" ]; then
        echo "The udev rule $rule_dst is left in place; remove it with: sudo rm $rule_dst && sudo udevadm control --reload"
    fi
    echo "Your profiles in $conf/m7ctl are kept."
    exit 0
fi

if [ ! -x "$bin" ]; then
    echo "building the release binary first..."
    (cd "$here" && cargo build --release)
fi

mkdir -p "$HOME/.local/bin"
if [ "$mode" = copy ]; then
    install -m755 "$bin" "$dest_bin"
    echo "copied $bin to $dest_bin"
else
    ln -sfn "$bin" "$dest_bin"
    echo "linked $dest_bin -> $bin"
fi

# completions and the man page are generated by the binary itself, so they always match its options
gen=$(mktemp -d); trap 'rm -rf "$gen"' EXIT
"$bin" completions bash > "$gen/m7ctl.bash"
"$bin" completions zsh > "$gen/_m7ctl"
"$bin" completions fish > "$gen/m7ctl.fish"
"$bin" man > "$gen/m7ctl.1"
install -Dm644 "$gen/m7ctl.bash" "$data/bash-completion/completions/m7ctl"
install -Dm644 "$gen/_m7ctl" "$data/zsh/site-functions/_m7ctl"
install -Dm644 "$gen/m7ctl.fish" "$conf/fish/completions/m7ctl.fish"
install -Dm644 "$gen/m7ctl.1" "$data/man/man1/m7ctl.1"
echo "installed shell completions (bash, zsh, fish) and the man page under $data and $conf"
echo "  zsh: make sure $data/zsh/site-functions is in your fpath"

case ":$PATH:" in
    *":$HOME/.local/bin:"*) ;;
    *) echo "note: $HOME/.local/bin is not in your PATH" ;;
esac

if [ "$udev" = yes ]; then
    # compare ignoring comment lines
    if [ -f "$rule_dst" ] && [ "$(grep -v '^#' "$rule_src")" = "$(grep -v '^#' "$rule_dst")" ]; then
        echo "udev rule already installed and up to date"
    else
        echo "installing the udev rule (sudo asks for your password) ..."
        if sudo install -m644 "$rule_src" "$rule_dst" && sudo udevadm control --reload \
            && sudo udevadm trigger --subsystem-match=hidraw --action=change; then
            echo "udev rule installed; replug the mouse or receiver if m7ctl says permission denied"
        else
            echo "could not install the udev rule; run in a terminal:  sudo install -m644 $rule_src $rule_dst" >&2
        fi
    fi
fi
echo "done: try  m7ctl status"
